package dev.abros.rivet.server;
import com.google.gson.*;
import com.mojang.brigadier.arguments.*;
import dev.abros.rivet.core.TradeBook;
import dev.abros.rivet.network.TradeWire;
import net.minecraft.commands.Commands;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.neoforge.network.PacketDistributor;
import java.util.*;
/** Read-only inspection is separate from participant containers; every request rechecks rights. */
final class TradeAdministration {
 static void register(net.neoforged.neoforge.event.RegisterCommandsEvent e){
  var root=Commands.literal("tradeadmin").requires(s->ServerCommands.allowed(s,"rivet.trade.view"))
   .executes(c->{list(c.getSource().getPlayerOrException(),0);return 1;})
   .then(Commands.literal("list").then(Commands.argument("page",IntegerArgumentType.integer(0,100000)).executes(c->{list(c.getSource().getPlayerOrException(),IntegerArgumentType.getInteger(c,"page"));return 1;})))
   .then(Commands.literal("inspect").then(Commands.argument("id",StringArgumentType.word()).then(Commands.argument("event",IntegerArgumentType.integer(-2)).then(Commands.argument("page",IntegerArgumentType.integer(0,100000)).executes(c->{detail(c.getSource().getPlayerOrException(),StringArgumentType.getString(c,"id"),IntegerArgumentType.getInteger(c,"event"),IntegerArgumentType.getInteger(c,"page"));return 1;})))))
   .then(Commands.literal("change").then(Commands.argument("id",StringArgumentType.word()).then(Commands.argument("revision",LongArgumentType.longArg(1)).then(Commands.argument("operation",StringArgumentType.word()).then(Commands.argument("reason",StringArgumentType.greedyString()).executes(c->{change(c.getSource().getPlayerOrException(),StringArgumentType.getString(c,"id"),LongArgumentType.getLong(c,"revision"),StringArgumentType.getString(c,"operation"),StringArgumentType.getString(c,"reason"));return 1;}))))));
  e.getDispatcher().register(Commands.literal("rivet").then(root));
 }
 private static ServerTrades allowed(ServerPlayer p,String right){var s=ServerTrades.require(p);if(!ServerCommands.allowed(p,"rivet.trade.view")||!ServerCommands.allowed(p,right))throw new IllegalArgumentException("trade.denied");return s;}
 private static JsonObject state(String mode,int page){var j=new JsonObject();j.addProperty("kind","tradeAdmin");j.addProperty("mode",mode);j.addProperty("page",page);return j;}
 private static void send(ServerPlayer p,JsonObject j,List<TradeWire.Change> icons){PacketDistributor.sendToPlayer(p,new TradeWire.State(j.toString(),icons));}
 static void list(ServerPlayer p,int page){try{var s=allowed(p,"rivet.trade.view");var all=new ArrayList<>(s.book.deals.values());Collections.reverse(all);var selected=all.stream().skip((long)page*12).limit(13).toList();var j=state("list",page);j.addProperty("more",selected.size()>12);var rows=new JsonArray();for(var d:selected.subList(0,Math.min(12,selected.size()))){var r=new JsonObject();r.addProperty("id",d.id);r.addProperty("createdAt",d.createdAt);r.addProperty("name",d.nameA+" ↔ "+d.nameB);r.addProperty("status",d.frozenAt>0?"frozen":d.status);r.addProperty("uuid",d.a);r.addProperty("uuidB",d.b);r.addProperty("nameA",d.nameA);r.addProperty("nameB",d.nameB);r.addProperty("online",false);r.addProperty("attention",d.frozenAt>0?"frozen":d.status);r.addProperty("expires",d.expires);var left=d.published(d.a);var right=d.published(d.b);r.addProperty("giveCount",left.size());r.addProperty("receiveCount",right.size());r.add("give",ServerTrades.previews(left,p));r.add("receive",ServerTrades.previews(right,p));rows.add(r);}j.add("rows",rows);send(p,j,List.of());}catch(Exception failure){ServerTrades.error(p,failure);}}
 static void detail(ServerPlayer p,String id,int event,int page){try{var s=allowed(p,"rivet.trade.view");var d=s.book.deals.get(id);if(d==null)throw new IllegalArgumentException("trade.denied");var j=state(event==-2?"history":"detail",page);j.addProperty("id",id);j.addProperty("createdAt",d.createdAt);j.addProperty("name",d.nameA+" ↔ "+d.nameB);j.addProperty("nameA",d.nameA);j.addProperty("nameB",d.nameB);j.addProperty("uuidA",d.a);j.addProperty("uuidB",d.b);j.addProperty("revision",d.revision);j.addProperty("event",event);j.addProperty("active",d.active());j.addProperty("frozen",d.frozenAt>0);j.addProperty("freeze",ServerCommands.allowed(p,"rivet.trade.freeze"));j.addProperty("cancel",ServerCommands.allowed(p,"rivet.trade.cancel"));var rows=new JsonArray();var icons=new ArrayList<TradeWire.Change>();var history=s.book.history.getOrDefault(id,List.of());
  if(event==-2){j.addProperty("pages",Math.max(1,(history.size()+11)/12));int end=Math.max(0,history.size()-page*12),start=Math.max(0,end-12);j.addProperty("more",start>0);for(int i=end-1;i>=start;i--){var a=history.get(i);var r=new JsonObject();r.addProperty("event",i);r.addProperty("at",a.at());r.addProperty("actor",a.actor().equals(d.a)?d.nameA:a.actor().equals(d.b)?d.nameB:a.actor());r.addProperty("action",a.action());r.addProperty("reason",a.reason());rows.add(r);}}
  else{List<TradeBook.Item> left=d.left,right=d.right;if(event>=0){if(event>=history.size())throw new IllegalArgumentException("trade.changed");var a=history.get(event);var snapshot=s.book.snapshots.get(a.snapshot());if(snapshot==null)throw new IllegalArgumentException("trade.changed");left=snapshot.left();right=snapshot.right();j.addProperty("action",a.action());j.addProperty("reason",a.reason());}j.addProperty("pages",Math.max(1,(Math.max(left.size(),right.size())+11)/12));j.addProperty("more",(long)(page+1)*12<Math.max(left.size(),right.size()));for(int side=0;side<2;side++){var items=side==0?left:right;for(int n=page*12;n<Math.min(items.size(),(page+1)*12);n++){var item=items.get(n);var stack=TradeItems.decode(item,p.registryAccess());var r=new JsonObject();r.addProperty("owner",side==0?d.nameA:d.nameB);r.addProperty("side",side);r.addProperty("slot",n%12);r.addProperty("count",item.count());rows.add(r);icons.add(new TradeWire.Change(side*24+n%12,stack,0,item.count()));}}}

  j.add("rows",rows);send(p,j,icons);
 }catch(Exception failure){ServerTrades.error(p,failure);}}
 static void change(ServerPlayer p,String id,long revision,String operation,String reason){try{String right=switch(operation){case "freeze","unfreeze"->"rivet.trade.freeze";case "cancel"->"rivet.trade.cancel";default->throw new IllegalArgumentException("trade.action");};var s=allowed(p,right);if(!s.available())throw new IllegalArgumentException("trade.busy");var next=s.copy();next.moderate(id,revision,p.getGameProfile().getName()+" ("+p.getStringUUID()+")",operation,reason,System.currentTimeMillis());s.commit(null,next,null,null,()->{s.refresh();detail(p,id,-1,0);});}catch(Exception failure){ServerTrades.error(p,failure);}}
 private TradeAdministration(){}
}
